/*
 * Protocol/content-manifest.c -- frozen content identity table (P2.2).
 *
 * Values are pinned to the Phase 1 golden manifests and the canonical
 * release preset.  The verification harness re-derives the source-asset
 * hashes and the content-set digest from the tree and compares them here;
 * do not edit a digest to bless a content change (D2-C, AGENTS.md).
 *
 * Source-of-record for the digests:
 *   Tests/phase1/content.golden.sha256   (assets, verbatim)
 *   Tests/phase1/geometry.golden.sha256  (geometry table)
 *   Tests/phase2/fixtures/protocol/release-preset.txt (canonical bytes)
 */

