const XtkContentEntry *xtk_content_lookup(uint16_t id)
{
    size_t i;
    for (i = 0; i < xtk_content_entry_count; ++i) {
        if (xtk_content_entries[i].id == id) {
            return &xtk_content_entries[i];
        }
    }
    return NULL;
}
